sheet = 'W1::Allowed assignments'
rows_data = cells(sheet, 'L812:N820')
tasks = list(set(r[0] for r in rows_data))
workers = list(set(r[1] for r in rows_data))
cost_map = {(r[0], r[1]): r[2] for r in rows_data}
max_tasks = 0
for k in range(len(tasks), 0, -1):
    found = False
    for t_combo in itertools.combinations(tasks, k):
        for w_perm in itertools.permutations(workers, k):
            valid = True
            for t, w in zip(t_combo, w_perm):
                if (t, w) not in cost_map:
                    valid = False
                    break
            if valid:
                found = True
                break
        if found:
            break
    if found:
        max_tasks = k
        break
result = max_tasks

